%[text] %[text:anchor:T_1FFD3858] # Longitudinal Vehicle - Simulation Case
%[text] %[text:anchor:H_1B376934] ## Accelerate
model_name = "HarnessModel_Vehicle1D";
load_system(model_name)

Vehicle1D_Basic_params

set_param(model_name + "/Longitudinal Vehicle", ReferencedSubsystem = "Vehicle1D_Basic_refsub");

set_param(model_name + "/Inputs", ReferencedSubsystem = "Inputs_Vehicle1D_Accelerate_refsub");
%[text] 
initial.vehicle_speed_kph = 0;

sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime = "300");

sim_out = sim(sim_in);

sim_data = extractTimetable(sim_out.logsout);

signal_names = [
  "Axle torque input"
  "Brake force"
  "Road inclination"
  "Road grade"
  "G force"
  "Vehicle speed kph"
  "Vehicle speed mph"
  "Axle speed"
  ];

for idx = 1 : numel(signal_names) %[output:group:643b67a6]
  fig = SignalTool2.plotTimedData(TimedData = sim_data, SignalName = signal_names(idx)); %[output:97a946ea] %[output:202b519c] %[output:025ea97d] %[output:16b2745f] %[output:092c4b3e] %[output:18adce0b] %[output:01fce1d5] %[output:955cd415]
  fig.Position(4) = 200;  % height
end  % for %[output:group:643b67a6]
